var maxSlidingWindow = function(nums, k) {
    const candidates = [];
    const maxima = [];

    for (let i = 0; i < nums.length; i++) {
        while (candidates.length && candidates[0] <= i - k) {
            candidates.shift();
        }
        while (candidates.length && nums[candidates[candidates.length - 1]] <= nums[i]) {
            candidates.pop();
        }
        candidates.push(i);

        if (i >= k - 1) {
            maxima.push(nums[candidates[0]]);
        }
    }

    return maxima;
};

solution.python:
from collections import deque
from typing import List

class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        candidates = deque()
        maxima = []

        for i, value in enumerate(nums):
            while candidates and candidates[0] <= i - k:
                candidates.popleft()
            while candidates and nums[candidates[-1]] <= value:
                candidates.pop()
            candidates.append(i)

            if i >= k - 1:
                maxima.append(nums[candidates[0]])

        return maxima
